create table if not exists customers(id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, address text, notes text, created_at timestamptz not null default now());
create table if not exists suppliers(id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, address text, notes text, created_at timestamptz not null default now());
create table if not exists employees(id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, address text, notes text, created_at timestamptz not null default now());
create table if not exists stock_movements(id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, quantity integer not null check(quantity <> 0), stock_before integer not null, stock_after integer not null, reason text not null default 'Manual adjustment', created_at timestamptz not null default now());
alter table customers enable row level security; alter table suppliers enable row level security; alter table employees enable row level security; alter table stock_movements enable row level security;
drop policy if exists "customers public access" on customers; drop policy if exists "suppliers public access" on suppliers; drop policy if exists "employees public access" on employees; drop policy if exists "stock movements public access" on stock_movements;
create policy "customers public access" on customers for all to anon, authenticated using (true) with check (true);
create policy "suppliers public access" on suppliers for all to anon, authenticated using (true) with check (true);
create policy "employees public access" on employees for all to anon, authenticated using (true) with check (true);
create policy "stock movements public access" on stock_movements for all to anon, authenticated using (true) with check (true);
create or replace function public.adjust_stock(p_product_id uuid,p_quantity integer,p_reason text) returns products language plpgsql security definer set search_path=public as $$ declare p products; before_qty integer; after_qty integer; begin if p_quantity=0 then raise exception 'Stock change cannot be zero'; end if; select * into p from products where id=p_product_id and is_active=true for update; if not found then raise exception 'Product not found'; end if; before_qty=p.stock_quantity; after_qty=before_qty+p_quantity; if after_qty<0 then raise exception 'Stock cannot go below 0'; end if; update products set stock_quantity=after_qty,updated_at=now() where id=p_product_id returning * into p; insert into stock_movements(product_id,quantity,stock_before,stock_after,reason) values(p_product_id,p_quantity,before_qty,after_qty,coalesce(nullif(trim(p_reason),''),'Manual adjustment')); return p; end; $$;
revoke all on function public.adjust_stock(uuid,integer,text) from public; grant execute on function public.adjust_stock(uuid,integer,text) to anon, authenticated;
